package dev.veltraph.client.navigation;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import dev.veltraph.client.world.Vec3;
final class WaterTerminalLeaseTest {
 @Test void exactPlanAuthorityAndNativeScopeRemainSameAcrossHolderTicks(){Object p=new Object(),a=new Object(),player=new Object(),w=new Object(),c=new Object();var receipt=new WaterTerminalLease(p,a,player,w,c,new Vec3(.5,70,.5),.18,0,500);for(int i=0;i<20;i++)assertTrue(receipt.valid(p,a,player,w,c,new Vec3(.5,70,.5),.18,true,100));}
 @Test void replacementAuthorityPwcDisabledAndCancelPermanentlyRevoke(){for(int which=0;which<6;which++){Object p=new Object(),a=new Object(),player=new Object(),w=new Object(),c=new Object();var receipt=new WaterTerminalLease(p,a,player,w,c,new Vec3(.5,70,.5),.18,0,500);assertFalse(receipt.valid(which==0?new Object():p,which==1?new Object():a,which==2?new Object():player,which==3?new Object():w,which==4?new Object():c,new Vec3(.5,70,.5),.18,which!=5,100));assertFalse(receipt.valid(p,a,player,w,c,new Vec3(.5,70,.5),.18,true,100));}Object p=new Object(),a=new Object(),player=new Object(),w=new Object(),c=new Object();var receipt=new WaterTerminalLease(p,a,player,w,c,new Vec3(.5,70,.5),.18,0,500);receipt.revoke();assertFalse(receipt.valid(p,a,player,w,c,new Vec3(.5,70,.5),.18,true,100));}
 @Test void checkpointRetainsExactLeaseObjectsAndRevocation(){Object p=new Object(),a=new Object(),player=new Object(),w=new Object(),c=new Object();var receipt=new WaterTerminalLease(p,a,player,w,c,new Vec3(.5,70,.5),.18,0,500);var checkpoint=receipt.maintenanceState();assertEquals(false,checkpoint.fields().get("revoked"));assertEquals(checkpoint,receipt.maintenanceState());receipt.revoke();assertNotEquals(checkpoint,receipt.maintenanceState());assertThrows(NullPointerException.class,()->new WaterTerminalLease(p,null,player,w,c,new Vec3(.5,70,.5),.18,0,500));}
 @Test void alteredGoalRadiusExpiryAndClockRollbackNeverRevive(){for(int which=0;which<4;which++){Object p=new Object(),a=new Object(),player=new Object(),w=new Object(),c=new Object();var goal=new Vec3(.5,70,.5);var receipt=new WaterTerminalLease(p,a,player,w,c,goal,.18,0,500);assertTrue(receipt.valid(p,a,player,w,c,goal,.18,true,200));assertFalse(receipt.valid(p,a,player,w,c,which==0?new Vec3(.6,70,.5):goal,which==1?.2:.18,true,which==2?501:which==3?199:201));assertFalse(receipt.valid(p,a,player,w,c,goal,.18,true,202));}}
 @Test void nonfiniteGoalCannotCreateTerminalReceipt(){Object p=new Object(),a=new Object(),player=new Object(),w=new Object(),c=new Object();for(Vec3 goal:new Vec3[]{new Vec3(Double.NaN,70,.5),new Vec3(.5,Double.POSITIVE_INFINITY,.5),new Vec3(.5,70,Double.NEGATIVE_INFINITY)})assertThrows(IllegalArgumentException.class,()->new WaterTerminalLease(p,a,player,w,c,goal,.18,0,500));}
}


